"288 :   public void traverseRoots(List<Node> roots) {
289 :     if (roots.isEmpty()) {
290 :       return;
291 :     }
292 : 
293 :     try {
294 :       Node scopeRoot = roots.get(0).getParent();
295 :       Preconditions.checkState(scopeRoot != null);
296 : 
297 :       inputId = NodeUtil.getInputId(scopeRoot);
298 :       sourceName = "";
299 :       curNode = scopeRoot;
300 :       pushScope(scopeRoot);
301 : 
302 :       for (Node root : roots) {
303 :         Preconditions.checkState(root.getParent() == scopeRoot);
304 :         traverseBranch(root, scopeRoot);
305 :       }
306 : 
307 :       popScope();
308 :     } catch (Exception unexpectedException) {
309 :       throwUnexpectedException(unexpectedException);
310 :     }
311 :   }"

"477 :   @SuppressWarnings("fallthrough")
478 :   private void traverseBranch(Node n, Node parent) {
479 :     int type = n.getType();
480 :     if (type == Token.SCRIPT) {
481 :       inputId = n.getInputId();
482 :       sourceName = getSourceName(n);
483 :     }
484 : 
485 :     curNode = n;
486 :     if (!callback.shouldTraverse(this, n, parent)) return;
487 : 
488 :     switch (type) {
489 :       case Token.FUNCTION:
490 :         traverseFunction(n, parent);
491 :         break;
492 : 
493 :       default:
494 :         for (Node child = n.getFirstChild(); child != null; ) {
495 :           // child could be replaced, in which case our child node
496 :           // would no longer point to the true next
497 :           Node next = child.getNext();
498 :           traverseBranch(child, n);
499 :           child = next;
500 :         }
501 :         break;
502 :     }
503 : 
504 :     curNode = n;
505 :     callback.visit(this, n, parent);
506 :   }"

